/// True when `name` is a stdlib module binding head.
#[must_use]
pub(crate) fn is_stdlib_module_name(name: &str) -> bool {
    STDLIB_MODULES.binary_search(&name).is_ok()
}

/// True when `path` names a canonical stdlib module path, or a namespace
/// prefix containing canonical child modules. This avoids materializing a
/// runtime set while keeping `use std::crypto`-style namespace imports valid.
#[must_use]
pub(crate) fn is_stdlib_module_path_or_namespace(path: &str) -> bool {
    if STDLIB_MODULE_PATHS.binary_search(&path).is_ok() {
        return true;
    }
    let idx = STDLIB_MODULE_PATHS.partition_point(|candidate| *candidate < path);
    STDLIB_MODULE_PATHS.get(idx).is_some_and(|candidate| {
        candidate.len() > path.len()
            && candidate.starts_with(path)
            && candidate.as_bytes()[path.len()] == b':'
    })
}

/// The canonical container name for a spelling that used to alias one,
/// or `None` when `name` is not a retired spelling. Each container has
/// exactly one name; these are reported with a rename hint rather than a
/// bare "not found".
pub(crate) fn canonical_collection_name(name: &str) -> Option<&'static str> {
    match name {
        "HashMap" => Some("Map"),
        "HashSet" => Some("Set"),
        "VecDeque" => Some("Deque"),
        "VecQueue" => Some("Queue"),
        "VecStack" => Some("Stack"),
        "BinaryHeap" | "MaxBinaryHeap" => Some("MaxHeap"),
        "MinBinaryHeap" => Some("MinHeap"),
        _ => None,
    }
}

/// True when the runtime binds this qualified stdlib callable/member name.
#[must_use]
pub fn is_stdlib_qualified(name: &str) -> bool {
    STDLIB_QUALIFIED.binary_search(&name).is_ok()
}

/// The macro this `std::`-relative path names, if it names one.
#[must_use]
pub fn stdlib_macro_named(path: &str) -> Option<&'static str> {
    STDLIB_MACRO_ITEMS
        .binary_search(&path)
        .ok()
        .and_then(|idx| STDLIB_MACRO_ITEMS.get(idx).copied())
        .and_then(|entry| entry.rsplit("::").next())
}

/// True when some entry of `table` equals `prefix` or extends it by a
/// further `::` segment. `table` must be sorted.
fn table_covers_prefix(table: &[&str], prefix: &str) -> bool {
    if table.binary_search(&prefix).is_ok() {
        return true;
    }
    let idx = table.partition_point(|candidate| *candidate < prefix);
    table.get(idx).is_some_and(|candidate| {
        candidate.len() > prefix.len()
            && candidate.starts_with(prefix)
            && candidate.as_bytes()[prefix.len()] == b':'
    })
}

/// True when `path` - a `std::`-relative path such as `sync::Mutex` or
/// `encoding::json::parse` - names an item its parent module exports.
///
/// Two sources agree on the export set: the manifest lists the
/// advertised item names, and the runtime table lists the bindings
/// keyed by the module's LAST segment (`json::parse` stands for
/// `encoding::json::parse`), including the `Type::method` forms that
/// establish a type export.
#[must_use]
pub fn is_stdlib_item_path(path: &str) -> bool {
    if STDLIB_MANIFEST_ITEMS.binary_search(&path).is_ok() {
        return true;
    }
    if table_covers_prefix(STDLIB_QUALIFIED, path) {
        return true;
    }
    let Some((module, item)) = path.rsplit_once("::") else {
        return false;
    };
    let leaf_module = module.rsplit("::").next().unwrap_or(module);
    table_covers_prefix(STDLIB_QUALIFIED, &format!("{leaf_module}::{item}"))
}

/// Item names the module at `module` (a `std::`-relative module path)
/// exports, for a did-you-mean over a misspelled import leaf.
#[must_use]
pub fn stdlib_module_item_names(module: &str) -> Vec<&'static str> {
    let leaf_module = module.rsplit("::").next().unwrap_or(module);
    let manifest_prefix = format!("{module}::");
    let runtime_prefix = format!("{leaf_module}::");
    let mut names: Vec<&'static str> = STDLIB_MANIFEST_ITEMS
        .iter()
        .filter_map(|entry| entry.strip_prefix(&manifest_prefix))
        .chain(
            STDLIB_QUALIFIED
                .iter()
                .filter_map(|entry| entry.strip_prefix(&runtime_prefix)),
        )
        .map(|rest| rest.split("::").next().unwrap_or(rest))
        .collect();
    names.sort_unstable();
    names.dedup();
    names
}

/// Whether any stdlib module exports `item` under that leaf name. A bare
/// `use Map` names an item two modules declare, so it has no sole owner
/// yet still names something real.
#[must_use]
pub(crate) fn is_stdlib_item_name(item: &str) -> bool {
    let suffix = format!("::{item}");
    STDLIB_MANIFEST_ITEMS
        .iter()
        .any(|entry| entry.ends_with(&suffix))
}

/// The single `std::`-relative module path exporting an item named
/// `item`, or `None` when no module or more than one module does.
///
/// A bare name that exactly one module owns has an unambiguous import,
/// so the unresolved-name report can name it.
#[must_use]
pub fn sole_stdlib_module_exporting(item: &str) -> Option<&'static str> {
    let suffix = format!("::{item}");
    let mut found: Option<&'static str> = None;
    for entry in STDLIB_MANIFEST_ITEMS {
        let Some(module) = entry.strip_suffix(&suffix) else {
            continue;
        };
        if found.is_some_and(|prev| prev != module) {
            return None;
        }
        found = Some(module);
    }
    found
}
/// Canonical stdlib path for a leaf-module spelling. `use
/// std::compress::gzip` puts the leaf module in scope, so the call
/// reads `gzip::encode(..)`; dispatch tables key on the full
/// `compress::gzip::encode`. Returns `None` when the path is already
/// canonical, is not a stdlib member, or when more than one module
/// would claim the same leaf spelling.
#[must_use]
pub fn canonical_stdlib_path(joined: &str) -> Option<&'static str> {
    if joined.split("::").count() != 2 {
        return None;
    }
    let suffix = format!("::{joined}");
    let mut found: Option<&'static str> = None;
    for candidate in STDLIB_QUALIFIED {
        if candidate.ends_with(&suffix) {
            if found.is_some() {
                return None;
            }
            found = Some(candidate);
        }
    }
    found
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_and_consistent() {
        assert!(
            STDLIB_MODULES.windows(2).all(|w| w[0] < w[1]),
            "STDLIB_MODULES not sorted/unique"
        );
        assert!(
            STDLIB_QUALIFIED.windows(2).all(|w| w[0] < w[1]),
            "STDLIB_QUALIFIED not sorted/unique"
        );
        assert!(
            STDLIB_MANIFEST_ITEMS.windows(2).all(|w| w[0] < w[1]),
            "STDLIB_MANIFEST_ITEMS not sorted/unique"
        );
        // Every qualified head is a listed module.
        for q in STDLIB_QUALIFIED {
            let head = q.split("::").next().unwrap();
            assert!(
                STDLIB_MODULES.binary_search(&head).is_ok(),
                "module {head} missing for {q}"
            );
        }
    }
}
